import{_ as t,c as s,o as l,j as e,a as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"四库全书提要","description":"子夏易传 - 四库全书提要","frontmatter":{"title":"四库全书提要","description":"子夏易传 - 四库全书提要"},"headers":[],"relativePath":"zh/classics/zixia/002.md","filePath":"zh/classics/zixia/002.md"}'),n={name:"zh/classics/zixia/002.md"};function r(c,a,o,p,d,u){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"四库全书提要",tabindex:"-1"},[i("四库全书提要 "),e("a",{class:"header-anchor",href:"#四库全书提要","aria-label":"Permalink to “四库全书提要”"},"​")],-1),e("p",null,"《子夏易传》·十一卷（内府藏本）",-1),e("p",null,"旧本题“卜子夏撰”。案说《易》之家，最古者莫若是书。其伪中生伪，至一至再而未已者，亦莫若是书。《唐会要》载开元七年诏：“子夏《易传》，近无习者，令儒官详定。”刘知几议曰：“《汉志》《易》有十三家而无子夏作传者，至梁阮氏《七录》，始有《子夏易》六卷，或云韩婴作，或云丁宽作。然据《汉书》，《韩易》十二篇，《丁易》八篇，求其符合，事殊隳刺，必欲行用，深以为疑。”",-1),e("p",null,"司马贞议亦曰“案刘向《七略》有《子夏易传》，但此书不行已久，今所存多失真本。荀勖《中经簿》云：《子夏传》四卷，或云丁宽。是先达疑非子夏矣。又《隋书·经籍志》云：《子夏传》残阙，梁六卷，今二卷。知其书错缪多矣。又王俭《七志》引刘向《七略》云：《易传》子夏，韩氏婴也。今题不称韩氏而载薛虞记，其质粗略，旨趣非远，无益后学”云云。是唐以前所谓《子夏传》，已为伪本。",-1),e("p",null,"晁说之《传易堂记》又称：“今号为《子夏传》者，乃唐张弧之《易》”（案弧唐末为大理寺评事，有《素履子》，别著录），是唐时又一伪本并行。故宋《国史志》以《假托子夏易传》与《真子夏易传》两列其目，而《崇文总目》亦称此书篇第，略依王氏，决非卜子夏之文也。",-1),e("p",null,"朱彝尊《经义考》，证以陆德明《经典释文》、李鼎祚《周易集解》、王应麟《困学纪闻》所引，皆今本所无。德明、鼎祚犹曰在张弧以前，应麟乃南宋末人，何以当日所见与今本又异？然则今本又出伪托，不但非子夏书，亦并非张弧书矣。流传既久，姑存以备一家云尔。（谨案：唐徐坚《初学记》以太宗御制升列历代之前，盖臣子尊君之大义。焦竑《国史经籍志》、朱彝尊《经义考》并踵前规。臣等编摩《四库》，初亦恭录御定《易经通注》、御纂《周易折中》、御纂《周易述义》弁冕诸经。仰蒙指示，命移冠国朝著述之首，俾尊卑有序而时代不淆。圣度谦冲，酌中立宪，实为千古之大公。",-1),e("p",null,"谨恪遵彝训，仍托始於《子夏易传》，并发凡於此，著《四库》之通例焉。又案：托名之书有知其赝作之人者，有不知其赝作之人者，不能一一归其时代，故《汉书·艺文志》仍从其所托之时代为次。今亦悉从其例。）",-1)])])}const f=t(n,[["render",r]]);export{_ as __pageData,f as default};
